package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import javax.sql.DataSource;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.ObjectNode;

/** Actual native permanent metadata storage. Metadata itself does not allocate entity generations. */
class CatalogDayAnalysisReservationTest {
    static final LocalDate DAY=LocalDate.of(2026,1,1);static final Instant TIME=Instant.parse("2026-01-01T17:12:00.123456Z");
    GenerationJdbcStoreTest f;CatalogDayAnalysisReservationLedger ledger;boolean mysql(){return false;}
    @BeforeEach void fixture(){f=mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();f.fixture();ledger=new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.source),"agent");}
    <T>T read(Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    <T>T write(Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.source));tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);return tx.execute(s->work.get());}
    ObjectNode metadata(String category,int count){
        String entity="fictional-new-entity",logical=CatalogDayAnalysisEligibilityService.logicalKey(category,entity);var n=JsonMapper.shared().createObjectNode().put("schema_version","catalog-day-analysis-reservation-v1").put("category",category).put("business_date",DAY.toString()).put("entity_id",entity).put("reservation_key",JdbcCatalogDayAnalysisReservations.key(category,DAY,entity)).put("logical_key",logical).put("generation",1).put("intent_id",JdbcFrozenInputs.stableId("intent",logical+":1")).put("trigger","new_entity").put("entity_revision_before",0).put("entity_revision_after",1).put("entity_generation_before",0).put("entity_identity_hash","a".repeat(64)).put("closure_hash","b".repeat(64)).put("grouping_hash","c".repeat(64)).put("reserved_at","2026-01-01T17:12:00.123456Z");var values=n.putArray("members");for(int i=0;i<count;i++)values.addObject().put("item_id",String.format(Locale.ROOT,"fictional-item-%03d",i)).put("run_id","fictional-run").put("source_id","fictional-source").put("root_id","fictional-root").put("input_hash","d".repeat(64)).put("body_hash","e".repeat(64)).put("fragment_result_hash","f".repeat(64)).put("final_result_hash","1".repeat(64)).put("member_revision",2);return n;
    }
    CatalogDayAnalysisReservationLedger.Stored proposed(String category,int count){return CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(metadata(category,count)));}
    @Test void NativeFourCategoriesFirstReceiptCompleteReplayAndMicrosecondsDoNotAllocate(){
        for(String category:List.of("agent","skill","workflow","model")){
            var service=new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.source),category);var proposed=proposed(category,100);assertNull(read(()->service.read(DAY,proposed.entityId())));var stored=write(()->service.append(proposed));assertEquals(proposed.json(),stored.json());assertEquals(100,stored.members().size());assertEquals(TIME,stored.reservedAt());var later=metadata(category,1);later.put("reserved_at","2026-01-01T17:13:00.123456Z");assertEquals(stored.json(),write(()->service.append(CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(later)))).json());assertEquals(stored.json(),read(()->new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.source),category).read(DAY,stored.entityId())).json());assertFalse(stored.toString().contains("fictional"));assertFalse(stored.members().getFirst().toString().contains("fictional"));assertThrows(UnsupportedOperationException.class,()->stored.members().clear());
        }assertEquals(4,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind<>'disposition'",Integer.class));
    }
    @Test void ActualOriginalDaySelectionsProduceCompleteNewAndAliasMetadata(){
        var outer=new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogDayAnalysisReservationTest.this.mysql();}};
        var actual=outer.new NewFixture();actual.terminal("skill");actual.completeSource();var captured=outer.eligibility(actual).capture(DAY);var selected=captured.selected().getFirst();var value=CatalogDayAnalysisReservationLedger.propose(captured,selected,selected.header().revision()+1,outer.completed.plusSeconds(90));assertEquals(selected.entity().entityId(),value.entityId());assertEquals(captured.evidence().original().closureHash(),value.closureHash());assertEquals(selected.entity().members().getFirst().bodyHash(),value.members().getFirst().bodyHash());assertEquals(0,actual.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertThrows(RuntimeException.class,()->CatalogDayAnalysisReservationLedger.propose(captured,selected,selected.header().revision()+1,outer.completed));
        var aliases=new CatalogDayAliasEvidenceTest(){@Override boolean mysql(){return CatalogDayAnalysisReservationTest.this.mysql();}};var alias=aliases.new AliasFixture();alias.terminal("model");alias.completeSource();var original=outer.eligibility(alias).capture(DAY);var join=original.selected().getFirst();var retained=CatalogDayAnalysisReservationLedger.propose(original,join,join.header().revision(),outer.completed.plusSeconds(90));assertEquals(2,retained.members().size());assertEquals(2,retained.generation());assertEquals(join.intentId(),retained.intentId());assertEquals(join.header().revision(),retained.entityRevisionAfter());assertEquals(2,alias.f.sends);
    }
    @Test void NativeHashRoleAliasAndTimestampDamageRejectOriginalReceipt(){
        var value=proposed("agent",1);write(()->ledger.append(value));String id=JdbcCatalogDayAnalysisReservations.id(value.reservationKey());assertEquals(1,f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],id));assertThrows(RuntimeException.class,()->read(()->ledger.read(DAY,value.entityId())));f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",JdbcGenerationLineage.hash(value.json()),id);
        f.jdbc.update("UPDATE jobs SET revision=1 WHERE id=?",id);assertThrows(RuntimeException.class,()->write(()->ledger.lockAndRead(DAY,value.entityId())));f.jdbc.update("UPDATE jobs SET revision=0 WHERE id=?",id);
        f.jdbc.update("UPDATE jobs SET operator_id='fictional-wrong-actor' WHERE id=?",id);assertThrows(RuntimeException.class,()->read(()->ledger.read(DAY,value.entityId())));f.jdbc.update("UPDATE jobs SET operator_id=? WHERE id=?",JdbcCatalogDayAnalysisReservations.ACTOR,id);
        f.jdbc.update("UPDATE jobs SET id='fictional-alias' WHERE id=?",id);assertThrows(RuntimeException.class,()->read(()->ledger.read(DAY,value.entityId())));f.jdbc.update("UPDATE jobs SET id=? WHERE id='fictional-alias'",id);
        f.jdbc.update("UPDATE jobs SET updated_at=created_at+INTERVAL '1' SECOND WHERE id=?",id);assertThrows(RuntimeException.class,()->read(()->ledger.read(DAY,value.entityId())));
    }
    @Test void ExactTransactionRolesAndWholeCallerRollback(){
        var value=proposed("agent",1);assertThrows(RuntimeException.class,()->ledger.read(DAY,value.entityId()));assertThrows(RuntimeException.class,()->ledger.lockAndRead(DAY,value.entityId()));assertThrows(RuntimeException.class,()->read(()->ledger.append(value)));assertThrows(RuntimeException.class,()->write(()->ledger.read(DAY,value.entityId())));assertThrows(RuntimeException.class,()->write(()->{ledger.append(value);throw new IllegalStateException("fictional caller rollback");}));assertNull(read(()->ledger.read(DAY,value.entityId())));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));
    }
    @Test void StrictWholeMetadataIdentityCapacityAndSortedMembers(){
        for(String field:List.of("reservation_key","intent_id","entity_identity_hash","closure_hash","grouping_hash","trigger","business_date","reserved_at","logical_key")){var n=metadata("agent",1);n.put(field,"fictional-invalid");assertThrows(RuntimeException.class,()->CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(n)));}
        assertThrows(RuntimeException.class,()->proposed("agent",101));var unknown=metadata("agent",1);unknown.put("unknown",true);assertThrows(RuntimeException.class,()->CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(unknown)));var duplicate=metadata("agent",2);((ObjectNode)duplicate.get("members").get(1)).put("item_id","fictional-item-000");assertThrows(RuntimeException.class,()->CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(duplicate)));var huge=metadata("agent",1);huge.put("logical_key","x".repeat(131072));assertThrows(GenerationFlowService.CapacityGuarded.class,()->CatalogDayAnalysisReservationLedger.parse(JdbcFrozenInputs.canonical(huge)));assertThrows(RuntimeException.class,()->new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.source),"model").append(proposed("agent",1)));
    }
    @Test void RealCommitAcknowledgmentLossReadsTheOneOriginalReceipt(){
        class Ack extends DataSourceTransactionManager {boolean lost;Ack(DataSource source){super(source);}@Override protected void doCommit(DefaultTransactionStatus status){super.doCommit(status);if(lost&&!status.isReadOnly()){lost=false;throw new org.springframework.dao.DataAccessResourceFailureException("fictional committed acknowledgment lost");}}}
        var manager=new Ack(f.source);var shared=new SharedWriteExecutor(new JdbcSharedWriteEntry(f.source),manager,()->25,n->{});var value=proposed("agent",1);var action=new SharedWriteExecutor.ActionContext(JdbcCatalogDayAnalysisReservations.action(value.reservationKey()),JdbcCatalogDayAnalysisReservations.id(value.reservationKey()),null);manager.lost=true;var committed=shared.execute(action,k->org.springframework.transaction.support.TransactionSynchronizationManager.isCurrentTransactionReadOnly()?ledger.read(DAY,value.entityId()):ledger.lockAndRead(DAY,value.entityId()),c->ledger.append(value));assertEquals(value.json(),committed.json());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(value.json(),shared.executePrepared(action,k->org.springframework.transaction.support.TransactionSynchronizationManager.isCurrentTransactionReadOnly()?ledger.read(DAY,value.entityId()):ledger.lockAndRead(DAY,value.entityId()),()->{throw new IllegalStateException("original receipt must precede preparation");}).json());
    }
    @Test void NativeWriterHoldsReceiptRowUntilCallerFinishes() throws Exception {
        var value=proposed("agent",1);write(()->ledger.append(value));if(!mysql())return;
        write(()->{assertNotNull(ledger.lockAndRead(DAY,value.entityId()));try(var connection=f.source.getConnection();var statement=connection.createStatement()){statement.execute("SET SESSION innodb_lock_wait_timeout=1");var rejected=assertThrows(java.sql.SQLException.class,()->statement.executeUpdate("UPDATE jobs SET revision=revision+1 WHERE id='"+JdbcCatalogDayAnalysisReservations.id(value.reservationKey())+"'"));assertEquals(1205,rejected.getErrorCode());}catch(java.sql.SQLException failure){throw new IllegalStateException(failure);}return true;});assertEquals(value.json(),read(()->ledger.read(DAY,value.entityId())).json());
    }
    @Test void ConstructorClosedCategoryAndMandatoryDependenciesPerformNoIo(){var storage=mock(JdbcCatalogDayAnalysisReservations.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisReservationLedger(storage,category));verifyNoInteractions(storage);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisReservationLedger(storage,"news_tech"));assertThrows(RuntimeException.class,()->new CatalogDayAnalysisReservationLedger(null,"agent"));var source=mock(DataSource.class);assertNotNull(new JdbcCatalogDayAnalysisReservations(source));verifyNoInteractions(source);}
}
